"""Preserve the actual final lesson order and add reading prerequisites and exercises."""
import json,re
from pathlib import Path
P=Path(__file__).resolve().parent
TOPICS={
'A04':('Anticipation(예비 동작)은 다음 행동의 방향과 힘을 미리 읽게 하는 준비입니다. 길게 움직이는 것만이 준비는 아닙니다. 강한 준비 자세 한 장을 빨리 만든 뒤 유지하는 방법도 있습니다. 시작 신호를 빠르게 주는 것과 실제 판정 시점을 앞당기는 것은 따로 조절할 수 있습니다.','대기·준비·타격 자세와 각 도착 시점을 적습니다. 전체 준비 시간은 같게 두고 준비 자세에 도착하는 속도만 바꿔 보세요. 강한 신호가 빨리 읽히는지 정상 속도에서 확인합니다.'),
'A05':('Key Pose(핵심 자세)는 동작의 의미가 가장 선명하게 드러나는 자세입니다. Silhouette(실루엣)은 겉 윤곽입니다. 관절을 많이 벌리는 것보다 힘이 향하는 방향과 균형을 한눈에 읽게 하는 것이 우선입니다. 공격 대상과 캐릭터가 놓인 깊이도 함께 봅니다.','가장 보여 주고 싶은 타격 순간을 고르고 무늬 없이 윤곽으로 보세요. 손발이 몸통에 겹치는 부분, 카메라에서 가려지는 부분, 실제 목표를 지나가는 경로를 각각 표시합니다.'),
'A06':('Follow-through(후속 동작)는 주요 행동 뒤에도 이어지는 움직임입니다. 공격 판정 종료, 다음 입력 허용, 대기 자세 복귀는 같은 순간일 필요가 없습니다. 타격의 여운을 남기는 자세와 다음 행동을 시작할 준비를 함께 설계해야 연결이 설득력 있게 보입니다.','공격 시간표에 판정 종료·다음 입력 가능·클립 종료를 세 줄로 적습니다. 다음 행동을 각 시점에 연결하며 발 미끄러짐과 자세 급변을 확인하고, 회수 동작의 경로를 따로 다듬습니다.'),
'A07':('Exaggeration(과장)은 무조건 크게 움직이는 것이 아니라 작고 단순한 화면에서 잃는 정보를 보완하는 선택입니다. Motion Capture(모션 캡처)는 사람의 움직임을 기록하는 방법이며 최종 화면의 전달력을 자동으로 보장하지는 않습니다. 배우와 캐릭터의 비례·카메라·재생 리듬을 다시 확인합니다.','같은 동작을 얼굴 확대, 전신, 실제 플레이 크기로 비교합니다. 사라진 단서 하나를 고르고 어깨·손·몸통의 변화로 보충하세요. 커진 동작이 캐릭터의 성격까지 바꾸지 않는지 확인합니다.'),
'A08':('Pose(포즈)는 각 부분의 위치와 방향이 함께 만든 몸의 상태입니다. 몸의 흐름을 잇는 선과 무게를 받치는 발은 자세를 읽는 도움선입니다. 그림에 그은 안내선을 실제 질량 중심의 정밀 계산 결과와 혼동하지 않습니다. 부분이 좋아도 전체 관계가 어색할 수 있습니다.','고개→어깨→몸통→골반→발 순으로 살핀 뒤 전체 윤곽으로 돌아옵니다. 손목 각도 하나를 바꾸어 팔과 손이 분리되어 읽히는지 보고, 원래 카메라에서도 같은 인상이 남는지 확인하세요.'),
'A09':('Squash and Stretch(압축과 늘이기)는 물체의 모양 변화로 물성과 힘을 표현하는 원리입니다. 단순 확대·축소와는 목적이 다를 수 있습니다. Blend Shape 또는 Morph Target(형태 변형 목표)은 미리 만든 다른 표면 형태를 섞어 원하는 윤곽을 만드는 방법입니다.','같은 궤적과 같은 시간으로 튀는 공 두 개를 만들고 하나에만 눌림과 복원을 넣습니다. 높이만 줄인 경우와 옆으로 퍼지는 경우를 비교하세요. 이후 캐릭터의 윤곽에 맞는 변형 목표를 직접 만듭니다.'),
'A10':('Hit Reaction(피격 반응)은 맞았다는 사실과 충격 방향을 보여주는 움직임입니다. Hitbox(공격 판정 영역)와 Hurtbox(피격 판정 영역)는 보이는 몸의 표면과 별도로 설정할 수 있습니다. 몸이 크게 꺾여도 캐릭터의 기준 위치와 다음 판정이 어떻게 이어지는지 함께 확인합니다.','머리·몸통·다리 피격과 약한·강한 충격을 구분합니다. 같은 공격을 연속으로 맞힐 때 보이는 포즈 때문에 다음 판정이 예기치 않게 빗나가는지 확인하고, 자세와 기준 위치를 다른 표시로 봅니다.'),
'A11':('Interpolation(보간)은 정해진 값 사이의 중간값을 만드는 계산입니다. Keyframe(키 프레임)은 제작자가 의도적으로 지정한 핵심 값과 시점입니다. 시작과 끝이 같아도 중간에서 어디에 얼마나 머무는지에 따라 속도와 힘의 인상이 달라집니다. 부드러움만으로 좋은 리듬을 판단할 수 없습니다.','같은 8프레임 구간에 준비·타격 키를 배치합니다. 선형 이동과 준비에 머문 뒤 빠르게 뻗는 움직임을 비교하세요. 화면을 멈춰 보기와 정상 재생을 번갈아, 핵심 자세가 읽히는 시간과 입력 반응을 확인합니다.'),
'A12':('Facial Animation(표정 애니메이션)은 눈꺼풀·눈썹·입과 턱의 관계로 감정을 전달합니다. 얼굴 구조가 다르면 같은 이동량도 다른 인상을 만듭니다. 표면을 직접 변형하는 방식과 그림을 바꾸는 방식 등 구현 선택보다 먼저 어떤 감정을 어느 화면 크기에서 읽힐지 정해야 합니다.','중립 얼굴과 목표 표정을 같은 크기로 비교합니다. 눈썹 하나, 눈꺼풀 하나씩 바꿔 인상이 달라지는 이유를 적고, 전신 화면에서는 머리와 몸짓이 그 감정을 함께 말하는지 확인하세요.'),
'A13':('Mirroring(좌우 반전)은 이동 방향 전환과 같은 뜻이 아닙니다. 어느 손이 앞서는지, 몸통의 어느 면이 카메라를 향하는지도 바뀔 수 있습니다. 2D 그림을 뒤집는 방식과 3D 뼈대·장비를 대응시키는 방식에서는 확인할 항목이 다릅니다. 글자와 비대칭 소품도 함께 점검합니다.','좌우 이동 방향과 실제 몸 방향을 다른 화살표로 그려 봅니다. 반전 뒤 무기를 쥔 손·장착 위치·문양·글자가 의도대로 유지되는지 확인하고, 카메라에서 공격 팔이 계속 읽히는지 비교하세요.'),
'A14':('Animation Blending(애니메이션 혼합)은 서로 다른 자세를 가중치에 따라 섞는 방법입니다. Weight(가중치)가 0이면 이전 자세, 1이면 다음 자세만 쓰는 간단한 예를 생각할 수 있습니다. 위치의 선형 혼합과 회전의 혼합은 같은 계산을 그대로 쓰는 것이 아니며, 긴 전환이 항상 좋은 결과도 아닙니다.','공격→걷기 전환을 짧게·길게 비교하고 첫 이동 반응과 발 위치를 봅니다. 상체 행동과 하체 지형 적응처럼 서로 다른 목적의 제어가 충돌할 때 어떤 부분을 우선할지 정하세요.'),
'A15':('Rig(리그)는 캐릭터를 움직이기 위한 뼈대와 제어 구조입니다. Skinning(스키닝)은 제어 변화가 표면에 반영되도록 연결하는 과정입니다. 작은 손가락도 여러 관절·손·캐릭터에 걸쳐 반복되므로 화면 크기와 필요한 접촉 표현에 맞춰 제어 범위를 정해야 합니다.','병목과 손잡이처럼 지름이 다른 물체 두 개를 잡게 합니다. 엄지와 손가락 접촉이 읽히는지 확인하고, 가까운 손과 먼 손의 표현 수준을 나눕니다. 게임 둘의 모습만 보고 하드웨어 성능을 단정하지 마세요.'),
'A16':('공격에는 보이는 무기의 궤적과 판정이 활성화되는 구간이 함께 있습니다. 플레이 카메라에서 겹쳐 보여도 깊이가 다르면 실제 경로는 빗나갈 수 있습니다. 판정 크기를 넓히는 일만으로 해결하면 눈에 보이는 도달 범위와 성공 조건이 어긋날 수 있습니다.','같은 공격을 플레이 시점과 위쪽 시점에서 봅니다. 경로는 유지한 채 판정 활성 시간만 바꾸어 어떤 포즈에서 맞는지 확인하세요. 애니메이션·게임플레이 담당자가 시작부터 접촉 순간과 다음 행동 시점을 함께 검토합니다.'),
'A17':('Forward Kinematics, FK(정방향 운동학)는 관절을 돌려 손끝의 결과를 만들고, Inverse Kinematics, IK(역방향 운동학)는 손끝 같은 목표에 맞는 관절 배치를 구합니다. 둘 다 정해진 뼈대와 제약 안에서 작동합니다. 표현에 필요한 굽힘이나 늘어남이 그 구조 밖에 있다면 리그 자체를 바꿔야 할 수 있습니다.','같은 팔에서 보통 굽힘·곧게 펴짐·늘이기·곡선 굽힘을 목표로 적습니다. 기존 제약으로 불가능한 형태를 확인하고, 추가 관절·보정 형태가 화면에 주는 이점과 제작·검수 비용을 함께 비교하세요.'),
'A18':('같은 방향을 보는 두 회전도 중간 경로와 각 부분이 따라가는 시각이 다르면 다른 몸짓이 됩니다. Animation Curve(애니메이션 곡선)는 시간에 따라 값이 어떻게 변하는지 나타냅니다. 여러 축을 움직이는 이 표현 기법은 수학적으로 모든 회전 문제를 해결하는 별도 표현법을 뜻하지 않습니다.','머리와 눈이 목표를 바라보는 동작을 만들고 한 축 회전, 숙였다 돌리기, 기울이며 돌리기를 비교합니다. 축마다 시작·도착 시간을 달리하고, 목과 몸통이 뒤따르는 순서가 상황에 맞는지 정상 속도에서 확인하세요.')}

for ident,(intro,practice) in TOPICS.items():
    f=P/'drafts'/f'{ident}.json';d=json.loads(f.read_text(encoding='utf8'));body=d.get('baseBody',d['body'])
    for a,b in [('삼차원','3D'),('이차원','2D'),('영 점 이 초','0.2초'),('영 점 오','0.5'),('열두 프레임','12프레임'),('키 프레임','키프레임')]:body=body.replace(a,b)
    body=re.sub(r'[^\n.!?]*(?:댓글로 알려|프로필.*링크|좋아요.*구독)[^\n.!?]*[.!?]','',body)
    body=body.replace('이 영상에서','이 장에서').replace('오늘은','여기서는')
    d.update(body='## 읽기 전에\n\n'+intro+'\n\n'+body.strip()+'\n\n## 직접 확인해 보기\n\n'+practice+'\n\n## 핵심 정리\n\n'+intro.split('. ')[0]+'.\n\n'+practice.split('. ')[0]+'.',status='editorially-reviewed-body-images-pending',editorialReview='Final v8 captions retained in lesson order; source section concepts reviewed; prerequisites, English terms, practical observation and limits added.')
    f.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
print('Prepared',len(TOPICS),'animation reading chapters.')
